var DATA={"label": "Foundation drill - label the seven pillars of the Signature ", "lengths": [10, 8], "angles": [40, 18]};

var x=0,y=0,a=0;
console.log('2-link arm FK ('+DATA.label+'): lengths ['+DATA.lengths.join(', ')+']');
DATA.lengths.forEach(function(L,i){
  a+=DATA.angles[i]*Math.PI/180;
  x+=L*Math.cos(a);y+=L*Math.sin(a);
  console.log('  joint '+(i+1)+': angle='+DATA.angles[i]+'deg -> ('+x.toFixed(3)+', '+y.toFixed(3)+')');});
console.log('End effector: ('+x.toFixed(3)+', '+y.toFixed(3)+')');
})();

