// Demo: Builder drill - run Inverse Kinematics Solver on a sample project and record
(function(){'use strict';
var DATA={"label": "Builder drill - run Inverse Kinematics Solver on a sample pr", "goal": "finds joint configurations for a desired robot pose.", "tools": [{"name": "inverse_kinematics", "purpose": "handle the inverse kinematics phase", "args": {"target": "inverse"}, "result": "ok: inverse kinematics complete", "done": false}, {"name": "slam", "purpose": "handle the slam phase", "args": {"target": "kinematics"}, "result": "ok: slam complete", "done": false}, {"name": "nvidia_isaac", "purpose": "handle the nvidia isaac phase", "args": {"target": "solver"}, "result": "ok: nvidia isaac complete", "done": false}, {"name": "unitree", "purpose": "handle the unitree phase", "args": {"target": "sampl"}, "result": "ok: unitree complete", "done": true}], "maxSteps": 4};

console.log('Agent run - goal: '+DATA.goal);
var obs='start';
for(var s=0;s<DATA.maxSteps;s++){
  var tool=DATA.tools[s%DATA.tools.length];
  console.log(' step '+(s+1)+' THOUGHT: need '+tool.purpose);
  console.log(' step '+(s+1)+' ACTION: '+tool.name+'('+JSON.stringify(tool.args)+')');
  obs=tool.result;
  console.log(' step '+(s+1)+' OBSERVATION: '+obs);
  if(tool.done){console.log('GOAL REACHED in '+(s+1)+' steps');break;}}
if(s>=DATA.maxSteps)console.log('STOPPED - step budget exhausted');
})();

